import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    // handle negative if needed, but here all inputs are positive
                } else {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    static int N, K;
    static int[] head, to, next;
    static int edgeCount = 0;

    static void addEdge(int u, int v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    static int[] order;
    static int[] parent;

    static void bfsOrder(int root) {
        order = new int[N];
        parent = new int[N + 1];
        int headIdx = 0, tailIdx = 0;
        order[tailIdx++] = root;
        parent[root] = 0;

        while (headIdx < tailIdx) {
            int u = order[headIdx++];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v != parent[u]) {
                    parent[v] = u;
                    order[tailIdx++] = v;
                }
            }
        }
    }

    static final int INF = 1000000000;
    static int[] maxUncovered;
    static int[] minCover;

    static boolean check(int R) {
        int centers = 0;
        for (int i = 1; i <= N; i++) {
            maxUncovered[i] = 0;
            minCover[i] = INF;
        }

        for (int i = N - 1; i >= 0; i--) {
            int u = order[i];

            if (maxUncovered[u] + minCover[u] <= R) {
                maxUncovered[u] = -INF;
            }

            if (maxUncovered[u] == R) {
                centers++;
                minCover[u] = 0;
                maxUncovered[u] = -INF;
            }

            int p = parent[u];
            if (p != 0) {
                if (maxUncovered[u] != -INF) {
                    if (maxUncovered[u] + 1 > maxUncovered[p]) {
                        maxUncovered[p] = maxUncovered[u] + 1;
                    }
                }
                if (minCover[u] != INF) {
                    if (minCover[u] + 1 < minCover[p]) {
                        minCover[p] = minCover[u] + 1;
                    }
                }
            }
        }

        int root = order[0];
        if (maxUncovered[root] >= 0) {
            centers++;
        }

        return centers <= K;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        N = scanner.nextInt();
        if (N <= 0) return;
        K = scanner.nextInt();

        head = new int[N + 1];
        for (int i = 0; i <= N; i++) head[i] = -1;
        to = new int[2 * (N - 1)];
        next = new int[2 * (N - 1)];

        for (int i = 0; i < N - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            addEdge(u, v);
            addEdge(v, u);
        }

        bfsOrder(1);

        maxUncovered = new int[N + 1];
        minCover = new int[N + 1];

        int low = 1, high = N, ans = N;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(ans);
    }
}
